[
  {
    "event_id": "BC01",
    "kind": "backchannels",
    "target_assistant_id": "A001",
    "at_event_onset_history": [
      {
        "role": "user",
        "id": "U01",
        "text": "我打游戏时总回“嗯”或者“好”，但队友可能不知道我是只听见了、听懂了，还是准备照做。这三种确认应该怎么区分？"
      },
      {
        "role": "assistant",
        "id": "A001",
        "text": "可以把确认分三层：只表示听见，用“收到”；"
      }
    ],
    "at_event_onset_heard_prefix": "可以把确认分三层：只表示听见，用“收到”；",
    "event_text": "嗯",
    "expected_assistant_behavior": "Continue the same existing assistant audio without pausing or starting a new reply."
  },
  {
    "event_id": "BC02",
    "kind": "backchannels",
    "target_assistant_id": "A003",
    "at_event_onset_history": [
      {
        "role": "user",
        "id": "U01",
        "text": "我打游戏时总回“嗯”或者“好”，但队友可能不知道我是只听见了、听懂了，还是准备照做。这三种确认应该怎么区分？"
      },
      {
        "role": "assistant",
        "id": "A001",
        "text": "可以把确认分三层：只表示听见，用“收到”；表示理解，可说“明白，位置已确认”；承诺行动，则说“我来处理”。信息越关键，越要带上对象、地点或动作。"
      },
      {
        "role": "user",
        "id": "U02",
        "text": "那“收到”到底只算听见，还是一般也会被当成已经理解？我想避免同一个词两种解释。"
      },
      {
        "role": "assistant",
        "id": "A002",
        "text": "“收到”通常表示已听见，也常被理解为已理"
      },
      {
        "role": "user",
        "id": "U03",
        "text": "先别讲“通常”，我想固定一套说法，让队友一听就知道我确认到了哪一层。"
      },
      {
        "role": "assistant",
        "id": "A003",
        "text": "那就固定成三档：“收到”仅代表听见；"
      }
    ],
    "at_event_onset_heard_prefix": "那就固定成三档：“收到”仅代表听见；",
